test.create_query:
CREATE TABLE tuple_element_array_{payload_size}
(
    a Array(Tuple(code UInt32, payload String))
)
ENGINE = MergeTree ORDER BY tuple()

test.fill_query:
INSERT INTO tuple_element_array_{payload_size}
SELECT arrayMap(
    i -> (
        toUInt32(number * 8 + i),
        randomString({payload_size})
    ),
    range(8)
)
FROM numbers_mt(50000)

test.query:
SELECT sum(arraySum(tupleElement(a, 'code')))
FROM tuple_element_array_{payload_size}
FORMAT Null

SELECT sum(arraySum(a.code))
FROM tuple_element_array_{payload_size}
FORMAT Null
